 const left=N.slice(),B=T.map(t=>t<0?-2:-1),W=st.w,seen=new Uint8Array(T.length),comps=[];
 for(let i=0;i<T.length;i++){if(seen[i]||T[i]<0)continue;const q=[i];seen[i]=1;for(let h=0;h<q.length;h++){const j=q[h],x=j%W;for(const n of [j-W,x>0?j-1:-1,x<W-1?j+1:-1,j+W]){if(n<0||n>=T.length||seen[n]||T[n]!==T[i])continue;seen[n]=1;q.push(n);}}comps.push(q);}
