 for(const q of comps){const t=T[q[0]];let c=perm[t];for(const j of q){if(c<0||left[c]<=0){c=-1;for(let d=0;d<k;d++)if(d!==t&&left[d]>0&&(c<0||left[d]>left[c]))c=d;if(c<0)c=left.findIndex(n=>n>0);}B[j]=c;left[c]--;}}
 for(let i=0;i<T.length;i++){if(T[i]<0||B[i]!==T[i])continue;const x0=i%W,y0=Math.floor(i/W),H=T.length/W;let done=false;
  for(let r=1;r<Math.max(W,H)&&!done;r++)for(let dy=-r;dy<=r&&!done;dy++)for(let dx=-r;dx<=r&&!done;dx++){if(Math.max(Math.abs(dx),Math.abs(dy))!==r)continue;const x=x0+dx,y=y0+dy;if(x<0||y<0||x>=W||y>=H)continue;const j=y*W+x;if(T[j]>=0&&B[j]!==T[i]&&B[i]!==T[j]){[B[i],B[j]]=[B[j],B[i]];done=true;}}}
