 if(r.board.some((v,i)=>(st.T[i]<0)!==(v===-2)))return null;
 for(const v of [...r.board,...r.tray]){if(!Number.isInteger(v)||v<-2||v>=k)return null;if(v>=0)cnt[v]--;}
 if(!cnt.every(n=>n===0))return null;
