  for(let q=0;q<dst.length&&dst.length<srcN;q++){const j=dst[q],x=j%W;for(const dy of [-1,0,1])for(const dx of [-1,0,1]){if(!dx&&!dy)continue;if(x+dx<0||x+dx>=W)continue;const n=j+dy*W+dx;if(n<0||n>=st.T.length||seen.has(n)||!free(n))continue;seen.add(n);dst.push(n);if(dst.length>=srcN)break;}}
